// EAR OS · Stripe Price-Lock v9.0 · Depósito 100 € Price-Lock SHA-256 (SSOT)
// crypto es módulo incorporado de Node disponible oficialmente en el Code node n8n.
const crypto = require('crypto');
const SSOT = { deposito: 100.00, split: { artista: 0.80, earOs: 0.10, vimume: 0.10 } };
const body = $input.first().json.body ?? $input.first().json;
const required = ['stripeSessionId', 'eventDate', 'clientPhone', 'clientEmail', 'totalPrice', 'lockSignature'];
const errores = required.filter(c => body[c] === undefined || body[c] === null || body[c] === '');
if (errores.length > 0) { return { valid: false, error: 'Faltan campos obligatorios: ' + errores.join(', ') }; }
const depositAmount = Number(body.depositAmount ?? SSOT.deposito);
if (depositAmount !== SSOT.deposito) { return { valid: false, error: 'Depósito debe ser exactamente 100,00 € (SSOT). Recibido: ' + depositAmount }; }
const firmasEsperadas = [crypto.createHash('sha256').update(JSON.stringify({ stripeSessionId: body.stripeSessionId, eventDate: body.eventDate, clientPhone: body.clientPhone, totalPrice: Number(body.totalPrice) })).digest('hex')];
const sinFirma = { ...body }; delete sinFirma.lockSignature;
firmasEsperadas.push(crypto.createHash('sha256').update(JSON.stringify(sinFirma)).digest('hex'));
firmasEsperadas.push(crypto.createHash('sha256').update(JSON.stringify(sinFirma) + 'EAR_OS_V1').digest('hex'));
const firmaValida = firmasEsperadas.includes(String(body.lockSignature).toLowerCase());
if (!firmaValida) { return { valid: false, error: 'lockSignature SHA-256 inválida. Esperadas: ' + firmasEsperadas.join(' | ') }; }
const total = Number(body.totalPrice);
return { valid: true, ...body, depositAmount, depositDeductible: SSOT.deposito, remainingToPay: +(total - SSOT.deposito).toFixed(2), lockConfirmed: true, split: { artista: +(total * SSOT.split.artista).toFixed(2), earOs: +(total * SSOT.split.earOs).toFixed(2), vimume: +(total * SSOT.split.vimume).toFixed(2) }, requestId: body.requestId ?? ('LOCK-' + Date.now()) };

